export function createGame(character='ryaba',random=Math.random,{difficulty='hard',eventRules={}}={}){const hero=CHARACTERS[character]||CHARACTERS.ryaba;const s={random,character:CHARACTERS[character]?character:'ryaba',mode:'playing',time:0,score:0,kills:0,level:1,xp:0,need:TUNING.progress.xpBase,ge:50,freeRerolls:0,revived:false,continuesUsed:0,spawnCredit:0,spawnTimer:.4,enemyId:0,bulletId:0,enemies:[],bullets:[],acorns:[],gems:[],worms:[],magnets:[],fx:[],attacks:[],passives:{speed:0,damage:0,haste:0,magnet:0,health:0,shots:0,size:0,experience:0},weapons:{},player:{x:WORLD.width/2,y:WORLD.height/2,r:19*1.08,hp:hero.hp,maxHp:hero.hp,inv:0},stats:{damageDealt:0,damageTaken:0,totalXp:0,gems:0,healed:0,magnets:0,rerolls:0,freeRerolls:0,paidRerolls:0,revivals:0,killsByType:Object.fromEntries(Object.keys(ENEMIES).map(id=>[id,0])),weapons:Object.fromEntries(Object.keys(WEAPONS).map(id=>[id,{damage:0,kills:0,attacks:0}]))},pending:0,choices:[],evolving:null,events:[],bonus:false,bonusStartedAt:null,awaitingBonusChoice:false,chest:{earned:false,opened:false,reward:null},bossEvents:{},bombs:[],zones:[],orbitals:[],ambientTimer:12,spawnView:{width:1100,height:850},...makeWorldObjects(WORLD.width,WORLD.height)};initDifficulty(s,difficulty,eventRules);s.weapons[hero.weapon]=makeWeapon();for(let i=0;i<TUNING.progress.initialGems;i++)s.gems.push({x:WORLD.width/2-530+random()*1060,y:WORLD.height/2-320+random()*640,value:1,tier:1});scatterSupplies(s,WORLD,resolveObstacles);return s;}
export function levelXpCost(level){return Math.round(TUNING.progress.xpBase+Math.pow(level<=1?0:level,TUNING.progress.xpPower)*TUNING.progress.xpFactor);}
function makeWeapon(){return {level:1,effect:null,cd:.2,volley:0,ammo:TUNING.progress.magazine,reload:0};}
export function choicePool(s){const pool=PASSIVES.filter(([id])=>s.passives[id]<(id==='shots'?TUNING.progress.shotLimit:PASSIVE_LIMITS[id]??Infinity)).map(([id,name,icon,description])=>({kind:'passive',id,name,icon,description}));for(const [id,w]of Object.entries(WEAPONS)){const held=s.weapons[id];if(held?.level>=5||id==='ak'&&s.character!=='rambo'||id==='martial'&&s.character!=='monk'||!held&&Object.keys(s.weapons).length>=3)continue;pool.push({kind:'weapon',id,name:w.name,icon:w.icon,description:held?upgradeCopy(id,held.level+1,TUNING,w.damage):w.description});}return pool;}
export function rollChoices(s){const pool=choicePool(s);s.choices=[];while(s.choices.length<3&&pool.length)s.choices.push(pool.splice(Math.floor(s.random()*pool.length),1)[0]);return s.choices;}
export function reroll(s,confirmation=null){if(s.mode!=='upgrade'||(s.freeRerolls===0&&(s.stats.paidRerolls>=PAID_REROLL_LIMIT||!consumeQuote(s,'reroll',confirmation))))return false;if(s.freeRerolls>0){s.freeRerolls--;s.stats.freeRerolls++;}else{s.ge-=confirmation.price;s.stats.paidRerolls++;}s.stats.rerolls++;rollChoices(s);return true;}
export function choose(s,index){if(s.mode!=='upgrade')return false;const c=s.choices[index];if(!c)return false;if(c.kind==='passive'&&s.passives[c.id]>=(c.id==='shots'?TUNING.progress.shotLimit:PASSIVE_LIMITS[c.id]??Infinity))return false;const oldReload=s.weapons.ak?weaponStats(s,'ak').reload:0;if(c.kind==='passive'){s.passives[c.id]++;if(c.id==='health'){s.player.maxHp+=PASSIVE_BONUSES.health;s.player.hp+=PASSIVE_BONUSES.health;s.stats.healed+=PASSIVE_BONUSES.health;}}else if(!s.weapons[c.id])s.weapons[c.id]=makeWeapon();else{const w=s.weapons[c.id];w.level++;if(c.id==='ak'&&w.reload===0)w.ammo+=TUNING.progress.magazinePerLevel;if(w.level===5){if(c.id==='ak'&&w.reload>0)w.reload*=weaponStats(s,'ak').reload/oldReload;s.mode='evolution';s.evolving=c.id;return true;}}if(s.weapons.ak?.reload>0&&oldReload>0)s.weapons.ak.reload*=weaponStats(s,'ak').reload/oldReload;finishChoice(s);return true;}
export function evolve(s,effect){if(s.mode!=='evolution'||!WEAPONS[s.evolving].effects.some(x=>x[0]===effect))return false;s.weapons[s.evolving].effect=effect;if(effect==='belt')s.weapons[s.evolving].reload=0;s.evolving=null;finishChoice(s);return true;}
function finishChoice(s){s.pending--;if(s.pending>0){s.mode='upgrade';rollChoices(s);}else {s.mode='playing';s.player.inv=Math.max(s.player.inv,TUNING.combat.guard);s.player.hurtFlash=0;retain(s.fx,f=>f.type!=='hurt-feathers');for(const e of s.enemies){const d=distance(e,s.player);if(d<TUNING.combat.guardRadius+e.r){const angle=d>0?Math.atan2(e.y-s.player.y,e.x-s.player.x):e.id*2.39996;const push=TUNING.combat.guardPush*(1-d/(TUNING.combat.guardRadius+e.r))/ENEMIES[e.type].weight;e.x=clamp(e.x+Math.cos(angle)*push,32,WORLD.width-32);e.y=clamp(e.y+Math.sin(angle)*push,45,WORLD.height-45);}}s.fx.push({type:'guard',x:s.player.x,y:s.player.y,r:115,life:1/3,max:1/3});}}
export function damagePlayer(s,amount=1){if(s.testFlags?.invincible||worldCombatSuppressed(s)||s.player.inv>0||s.mode!=='playing')return;s.player.hp=Math.max(0,s.player.hp-amount);s.stats.damageTaken+=amount;s.player.inv=TUNING.combat.invulnerability;s.player.hurtFlash=TUNING.combat.invulnerability;s.fx.push({type:'hurt-feathers',x:s.player.x,y:s.player.y,r:48,life:.65,max:.65});s.events.push('hurt');if(s.player.hp<=0){s.mode=canRevive(s)?'revive':'ended';s.events.push(s.mode==='revive'?'revive-offer':'end');}}
export function enemyHpScale(time){const t=Math.min(time,TUNING.bosses.turkeyAt);return 1+TUNING.growth.hpLinear*t/TUNING.flow.hpGrowth+TUNING.growth.hpCubic*Math.pow(t/TUNING.bosses.turkeyAt,TUNING.growth.hpExponent);}
export function runTime(s){return Math.max(0,s.time-(s.bossPausedSeconds||0));}
export function progressionTime(s){let t=runTime(s);for(const e of s.enemies)if(e.hp>0&&ENEMIES[e.type]?.isBoss)t=Math.min(t,e.freezeAt??s.time);return phaseProgression(s,t,TUNING.bosses.guineaAt);}
export function bonusAge(s){return s.bonus&&s.bonusStartedAt!=null?Math.max(0,s.time-s.bonusStartedAt)/4:0;}
export function enemySpeedScale(s,type){const d=ENEMIES[type];if(d.isBoss)return 1;return (1+d.lateBoost*clamp((progressionTime(s)-TUNING.growth.lateStart)/Math.max(1,TUNING.growth.lateEnd-TUNING.growth.lateStart),0,1))*Math.min(TUNING.flow.bonusSpeedCap,1+bonusAge(s)/TUNING.flow.bonusHp);}
export function spawnEnemy(s,type,position=null){if(worldCombatSuppressed(s)||(s.testFlags?.noSpawns&&!ENEMIES[type]?.isBoss&&!position?.force))return null;const d=ENEMIES[type];if(!d)return null;if(d.isBoss){const existing=s.enemies.find(e=>e.type===type&&e.hp>0);if(existing)return existing;}else if(s.enemies.length>=TUNING.flow.maxEnemies)return null;const {x,y}=localSpawn(s,WORLD,d.r);const hp=d.hp*(d.isBoss?1:enemyHpScale(progressionTime(s))*(1+bonusAge(s)/TUNING.flow.bonusHp));const e={id:++s.enemyId,type,x,y,r:d.r,hp,maxHp:hp,speed:d.speed*(d.isBoss?1:TUNING.flow.speedScale),shot:2+s.random()*2,dash:s.random()*TUNING.behaviour.foxWarning,flash:0,freezeAt:runTime(s),attack:null,attackCd:2,attackIndex:0};if(position&&Number.isFinite(position.x)&&Number.isFinite(position.y)){e.x=clamp(position.x,-WORLD.spawnPadding,WORLD.width+WORLD.spawnPadding);e.y=clamp(position.y,-WORLD.spawnPadding,WORLD.height+WORLD.spawnPadding);e.eventHunt=position.eventHunt===true;e.ringSlot=position.ringSlot;}if(!d.isBoss)resolveObstacles(e,s.obstacles);scaleSpawn(s,e);s.enemies.push(e);if(d.isBoss){s.bossEvents[type]='alive';s.events.push('boss:'+type);}return e;}
export const SPAWN_STAGES=[{start:0,type:'rat'},{start:65,type:'fox'},{start:110,type:'duck'},{start:165,type:'squirrel'},{start:220,type:'wolf'},{start:270,type:'goose'},{start:420,type:'bear'}];
export function spawnProfile(time){const stages=[...SPAWN_STAGES].sort((a,b)=>a.start-b.start),stage=stages.filter(x=>x.start<=time).at(-1)||stages[0],age=Math.max(0,time-stage.start),t=TUNING.flow,w=TUNING.weights;const weights=Object.fromEntries(stages.filter(x=>x.start<=time&&!(x.type==='rat'&&time>=420)).map(x=>[x.type,x.type==='fox'&&time>=w.foxLateAt?w.foxLate:x.type==='wolf'&&time>=w.wolfLateAt?w.wolfLate:w[x.type]]));if(stage.start>0&&age<t.introDuration){const focus=1-age/t.introDuration;for(const key in weights)weights[key]*=key===stage.type?1+focus*5:1-focus*.8;}if(stage.type==='bear'&&age>=t.introDuration)weights.bear=Math.max(w.bear,2.4);return {stage:stage.type,age,weights,ramp:stage.start===0?1:Math.min(1,t.rampStart+age/t.introDuration*(1-t.rampStart))};}
export function enemyCost(type,time){const c=TUNING.costs,w=TUNING.weights;return type==='fox'&&time>=w.foxLateAt?c.foxLate:type==='wolf'&&time>=w.wolfLateAt?c.wolfLate:c[type];}
