export function updateBossPhase(e){if(ENEMIES[e.type]?.isBoss&&e.hp>0&&e.hp<=e.maxHp*.5)e.enraged=true;}
export function bossAttackRate(e){return .85*(e.enraged?(e.type==='turkey'?1.30:1.20):1);}
