 if(!e.attack&&e.attackCd===0){const shape=phasedBossAttack(e,selectEnemyAttack(e.type,distance(e,p),e.attackIndex));if(e.type==='turkey'&&shape.kind==='pecks')Object.assign(shape,turkeyPeckGeometry(e.r,TUNING.bosses));if(distance(e,p)<(shape.kind==='pecks'?shape.range+shape.width+p.r+12:e.type==='goose'?shape.range+45:e.type==='guinea'?Math.max(shape.range+80,TUNING.bosses.guineaEngage):Math.max(shape.range+80,TUNING.bosses.turkeyEngage))){e.attack={...shape,elapsed:0,phase:'windup',originX:e.x,originY:e.y,angle:Math.atan2(p.y-e.y,p.x-e.x),hitPulses:new Set()};e.attackIndex++;}}
