 if(a.kind==='pecks'){a.targets??=[];const marked=Math.min(TUNING.bosses.peckCount,Math.floor(Math.min(a.elapsed,a.windup-.00001)/(a.windup/TUNING.bosses.peckCount))+1);while(a.targets.length<marked)a.targets.push({x:p.x,y:p.y,angle:Math.atan2(p.y-e.y,p.x-e.x)});}
